// Auto-generated SQL scripts from supabase/migrations
export const INITIAL_MIGRATION_SQL = "-- ==============================================================================\n-- HỆ THỐNG QUẢN LÝ BÁO CÁO VÀ PHÂN TÍCH CHỈ SỐ THỦ TỤC HÀNH CHÍNH (TTHC)\n-- TẬP TIN 001: ĐỊNH NGHĨA CƠ SỞ DỮ LIỆU TOÀN DIỆN (SCHEMA ONLY)\n-- PHIÊN BẢN: 4.0 ENTERPRISE HARDENED & ROLE SECURED\n-- ĐẶC TÍNH: 100% IDEMPOTENT / ZERO BACKDOORS / BẢO VỆ PROFILES / RLS BẤT KHẢ XÂM PHẠM\n-- ==============================================================================\n\n-- ==============================================================================\n-- 1. EXTENSIONS\n-- ==============================================================================\nCREATE EXTENSION IF NOT EXISTS \"uuid-ossp\";\nCREATE EXTENSION IF NOT EXISTS \"pgcrypto\";\n\n-- ==============================================================================\n-- 2. DỌN DẸP VIEW/BẢNG CŨ NẾU CÓ (LOẠI BỎ TOÀN BỘ LEGACY OBJECTS)\n-- ==============================================================================\nDROP VIEW IF EXISTS public.reporting_periods CASCADE;\nDROP VIEW IF EXISTS public.report_statistics CASCADE;\nDROP VIEW IF EXISTS public.procedure_statistics CASCADE;\n\n-- ==============================================================================\n-- 3. ĐỊNH NGHĨA 11 BẢNG DỮ LIỆU CỐT LÕI\n-- ==============================================================================\n\n-- BẢNG 1: units (Đơn vị hành chính cấp phòng ban)\nCREATE TABLE IF NOT EXISTS public.units (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  code TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  display_order INTEGER NOT NULL DEFAULT 1,\n  active BOOLEAN NOT NULL DEFAULT true,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- BẢNG 2: profiles (Hồ sơ người dùng & phân quyền RBAC, liên kết auth.users)\nCREATE TABLE IF NOT EXISTS public.profiles (\n  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n  email TEXT,\n  full_name TEXT NOT NULL,\n  role TEXT NOT NULL DEFAULT 'viewer' CHECK (role IN ('admin', 'analyst', 'data_entry', 'viewer')),\n  unit_id UUID REFERENCES public.units(id) ON DELETE SET NULL,\n  active BOOLEAN NOT NULL DEFAULT true,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- BẢNG 3: fields (Lĩnh vực TTHC - mỗi lĩnh vực thuộc đúng 1 đơn vị)\nCREATE TABLE IF NOT EXISTS public.fields (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  code TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  unit_id UUID NOT NULL REFERENCES public.units(id) ON DELETE RESTRICT,\n  display_order INTEGER NOT NULL DEFAULT 1,\n  active BOOLEAN NOT NULL DEFAULT true,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- BẢNG 4: reports (Kỳ báo cáo tổng hợp TTHC và vòng đời nghiêm ngặt)\nCREATE TABLE IF NOT EXISTS public.reports (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  report_code TEXT NOT NULL UNIQUE,\n  report_name TEXT NOT NULL,\n  report_type TEXT NOT NULL DEFAULT 'monthly' CHECK (report_type IN ('weekly', 'monthly', 'quarterly', 'annual', 'ad_hoc')),\n  period_start DATE NOT NULL,\n  period_end DATE NOT NULL,\n  data_as_of TIMESTAMPTZ NOT NULL,\n  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'imported', 'validated', 'submitted', 'approved', 'locked', 'archived')),\n  created_by TEXT NOT NULL DEFAULT 'Hệ thống',\n  notes TEXT,\n  approved_at TIMESTAMPTZ,\n  approved_by TEXT,\n  locked_at TIMESTAMPTZ,\n  locked_by TEXT,\n  archived_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  CONSTRAINT check_period_dates CHECK (period_end >= period_start)\n);\n\n-- BẢNG 5: report_sources (Nguồn dữ liệu nhập khẩu cho từng kỳ báo cáo)\nCREATE TABLE IF NOT EXISTS public.report_sources (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  report_id UUID NOT NULL REFERENCES public.reports(id) ON DELETE CASCADE,\n  source_type TEXT NOT NULL DEFAULT 'system' CHECK (source_type IN ('system', 'excel', 'api', 'manual')),\n  source_name TEXT NOT NULL,\n  original_filename TEXT,\n  uploaded_by TEXT NOT NULL DEFAULT 'Hệ thống',\n  uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  import_status TEXT NOT NULL DEFAULT 'completed' CHECK (import_status IN ('pending', 'processing', 'completed', 'failed')),\n  notes TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  CONSTRAINT uq_report_source_name UNIQUE (report_id, source_name)\n);\n\n-- BẢNG 6: report_field_statistics (Số liệu thống kê TTHC chi tiết theo REPORT + SOURCE + FIELD)\nCREATE TABLE IF NOT EXISTS public.report_field_statistics (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  report_id UUID NOT NULL REFERENCES public.reports(id) ON DELETE CASCADE,\n  source_id UUID NOT NULL REFERENCES public.report_sources(id) ON DELETE CASCADE,\n  field_id UUID NOT NULL REFERENCES public.fields(id) ON DELETE RESTRICT,\n  field_name_snapshot TEXT NOT NULL,\n  unit_id UUID NOT NULL REFERENCES public.units(id) ON DELETE RESTRICT,\n  unit_name_snapshot TEXT NOT NULL,\n  \n  -- Nhóm 1: Tiếp nhận (CT1: received_total = received_online + received_offline + carried_forward)\n  received_total INTEGER NOT NULL DEFAULT 0 CHECK (received_total >= 0),\n  received_online INTEGER NOT NULL DEFAULT 0 CHECK (received_online >= 0),\n  received_offline INTEGER NOT NULL DEFAULT 0 CHECK (received_offline >= 0),\n  carried_forward INTEGER NOT NULL DEFAULT 0 CHECK (carried_forward >= 0),\n  \n  -- Nhóm 2: Đã giải quyết (CT2: completed_total = completed_early + completed_on_time + completed_late)\n  completed_total INTEGER NOT NULL DEFAULT 0 CHECK (completed_total >= 0),\n  completed_early INTEGER NOT NULL DEFAULT 0 CHECK (completed_early >= 0),\n  completed_on_time INTEGER NOT NULL DEFAULT 0 CHECK (completed_on_time >= 0),\n  completed_late INTEGER NOT NULL DEFAULT 0 CHECK (completed_late >= 0),\n  \n  -- Nhóm 3: Đang giải quyết (CT3: pending_total = pending_on_time + pending_late)\n  pending_total INTEGER NOT NULL DEFAULT 0 CHECK (pending_total >= 0),\n  pending_on_time INTEGER NOT NULL DEFAULT 0 CHECK (pending_on_time >= 0),\n  pending_late INTEGER NOT NULL DEFAULT 0 CHECK (pending_late >= 0),\n  \n  -- Trạng thái kiểm chứng toán học (CT4: received_total = completed_total + pending_total)\n  notes TEXT,\n  validation_status TEXT NOT NULL DEFAULT 'valid' CHECK (validation_status IN ('valid', 'warning', 'error')),\n  validation_errors JSONB NOT NULL DEFAULT '[]'::jsonb,\n  \n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  \n  CONSTRAINT uq_report_source_field UNIQUE (report_id, source_id, field_id)\n);\n\n-- BẢNG 7: indicator_definitions (Từ điển danh mục định nghĩa công thức chỉ số)\nCREATE TABLE IF NOT EXISTS public.indicator_definitions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  code TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  formula_key TEXT NOT NULL,\n  unit_measure TEXT NOT NULL DEFAULT '%',\n  target_value NUMERIC(10, 2),\n  description TEXT,\n  display_order INTEGER NOT NULL DEFAULT 1,\n  active BOOLEAN NOT NULL DEFAULT true,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- BẢNG 8: report_indicators (Số liệu chỉ số đo lường đã tính toán của kỳ báo cáo)\nCREATE TABLE IF NOT EXISTS public.report_indicators (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  report_id UUID NOT NULL REFERENCES public.reports(id) ON DELETE CASCADE,\n  indicator_definition_id UUID NOT NULL REFERENCES public.indicator_definitions(id) ON DELETE RESTRICT,\n  scope_type TEXT NOT NULL DEFAULT 'global' CHECK (scope_type IN ('global', 'unit', 'field')),\n  scope_id UUID,\n  calculated_value NUMERIC(12, 4) NOT NULL,\n  formatted_value TEXT NOT NULL,\n  target_status TEXT NOT NULL DEFAULT 'achieved' CHECK (target_status IN ('achieved', 'warning', 'critical')),\n  calculation_details JSONB DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Partial Unique Indexes cho report_indicators\nALTER TABLE public.report_indicators DROP CONSTRAINT IF EXISTS uq_report_indicator_scope;\n\nCREATE UNIQUE INDEX IF NOT EXISTS uq_report_indicators_global \nON public.report_indicators (report_id, indicator_definition_id) \nWHERE scope_type = 'global';\n\nCREATE UNIQUE INDEX IF NOT EXISTS uq_report_indicators_unit \nON public.report_indicators (report_id, indicator_definition_id, scope_id) \nWHERE scope_type = 'unit';\n\nCREATE UNIQUE INDEX IF NOT EXISTS uq_report_indicators_field \nON public.report_indicators (report_id, indicator_definition_id, scope_id) \nWHERE scope_type = 'field';\n\n-- BẢNG 9: report_analysis (Nhận xét, đánh giá và phân tích chuyên môn của báo cáo)\nCREATE TABLE IF NOT EXISTS public.report_analysis (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  report_id UUID NOT NULL REFERENCES public.reports(id) ON DELETE CASCADE,\n  scope_type TEXT NOT NULL DEFAULT 'overview' CHECK (scope_type IN ('overview', 'unit', 'field')),\n  scope_id UUID,\n  title TEXT NOT NULL,\n  generated_text TEXT NOT NULL,\n  generated_by TEXT NOT NULL DEFAULT 'Hệ thống',\n  source_metrics JSONB DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- BẢNG 10: report_snapshots (Bản chụp đóng băng bất biến khi báo cáo đạt trạng thái locked)\nCREATE TABLE IF NOT EXISTS public.report_snapshots (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  report_id UUID NOT NULL REFERENCES public.reports(id) ON DELETE RESTRICT,\n  version_number INTEGER NOT NULL DEFAULT 1,\n  snapshot_json JSONB NOT NULL,\n  created_by TEXT NOT NULL,\n  reason TEXT NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  CONSTRAINT uq_report_snapshot_version UNIQUE (report_id, version_number)\n);\n\n-- BẢNG 11: audit_logs (Nhật ký kiểm toán hệ thống append-only)\nCREATE TABLE IF NOT EXISTS public.audit_logs (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id TEXT NOT NULL,\n  action TEXT NOT NULL,\n  entity_type TEXT NOT NULL,\n  entity_id TEXT NOT NULL,\n  metadata JSONB DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- ==============================================================================\n-- 4. HELPER FUNCTIONS & TRIGGER PROCEDURES\n-- ==============================================================================\n\n-- 4.1 Hàm lấy vai trò người dùng an toàn (SECURITY DEFINER, chống recursion RLS)\nCREATE OR REPLACE FUNCTION public.current_user_role()\nRETURNS TEXT\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\n  SELECT role FROM public.profiles WHERE id = auth.uid() AND active = true LIMIT 1;\n$$;\n\n-- 4.2 Hàm cập nhật updated_at\nCREATE OR REPLACE FUNCTION public.set_updated_at_timestamp()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$;\n\n-- 4.3 Trigger bảo vệ toàn diện public.profiles chống leo thang đặc quyền (INSERT & UPDATE)\nCREATE OR REPLACE FUNCTION public.protect_profiles_privilege_escalation()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_caller_role TEXT;\nBEGIN\n  -- Lấy vai trò của người dùng hiện tại đang thực thi lệnh\n  v_caller_role := public.current_user_role();\n\n  -- Trường hợp INSERT: Người dùng mới tự tạo hồ sơ hoặc non-admin tạo\n  IF TG_OP = 'INSERT' THEN\n    IF COALESCE(v_caller_role, '') <> 'admin' THEN\n      -- Bắt buộc chỉ được tạo tài khoản cho chính mình\n      IF auth.uid() IS NOT NULL AND NEW.id <> auth.uid() THEN\n        RAISE EXCEPTION 'Bạn chỉ được phép khởi tạo hồ sơ cho chính tài khoản của mình.';\n      END IF;\n      -- Bắt buộc vai trò ban đầu phải là viewer, active = true, unit_id = NULL\n      NEW.role := 'viewer';\n      NEW.active := true;\n      NEW.unit_id := NULL;\n    END IF;\n    RETURN NEW;\n  END IF;\n\n  -- Trường hợp UPDATE: Non-admin không được tự ý sửa role, active, unit_id\n  IF TG_OP = 'UPDATE' THEN\n    IF COALESCE(v_caller_role, '') <> 'admin' THEN\n      IF NEW.role IS DISTINCT FROM OLD.role THEN\n        RAISE EXCEPTION 'Bạn không có quyền thay đổi vai trò (role) của tài khoản.';\n      END IF;\n\n      IF NEW.active IS DISTINCT FROM OLD.active THEN\n        RAISE EXCEPTION 'Bạn không có quyền thay đổi trạng thái hoạt động (active) của tài khoản.';\n      END IF;\n\n      IF NEW.unit_id IS DISTINCT FROM OLD.unit_id THEN\n        RAISE EXCEPTION 'Bạn không có quyền thay đổi đơn vị trực thuộc (unit_id) của tài khoản.';\n      END IF;\n    END IF;\n    RETURN NEW;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 4.4 Hàm ghi nhật ký kiểm toán bảo mật duy nhất qua SECURITY DEFINER (write_audit_log)\nCREATE OR REPLACE FUNCTION public.write_audit_log(\n  p_action TEXT,\n  p_entity_type TEXT,\n  p_entity_id TEXT,\n  p_metadata JSONB DEFAULT '{}'::jsonb\n)\nRETURNS UUID\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_log_id UUID;\n  v_user_id TEXT;\nBEGIN\n  -- Tự động trích xuất danh tính người dùng từ auth.uid() của session\n  v_user_id := COALESCE(auth.uid()::text, 'system');\n\n  INSERT INTO public.audit_logs (\n    id,\n    user_id,\n    action,\n    entity_type,\n    entity_id,\n    metadata,\n    created_at\n  ) VALUES (\n    gen_random_uuid(),\n    v_user_id,\n    p_action,\n    p_entity_type,\n    p_entity_id,\n    COALESCE(p_metadata, '{}'::jsonb),\n    now()\n  ) RETURNING id INTO v_log_id;\n\n  RETURN v_log_id;\nEND;\n$$;\n\n-- 4.5 Hàm kiểm tra scope_id của report_indicators\nCREATE OR REPLACE FUNCTION public.validate_report_indicator_scope()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  IF NEW.scope_type = 'global' THEN\n    IF NEW.scope_id IS NOT NULL THEN\n      RAISE EXCEPTION 'Chỉ số phạm vi toàn cơ quan (global) phải có scope_id là NULL.';\n    END IF;\n  ELSIF NEW.scope_type = 'unit' THEN\n    IF NEW.scope_id IS NULL THEN\n      RAISE EXCEPTION 'Chỉ số phạm vi đơn vị (unit) bắt buộc phải có scope_id.';\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = NEW.scope_id) THEN\n      RAISE EXCEPTION 'scope_id (%) không tồn tại trong danh mục đơn vị (public.units).', NEW.scope_id;\n    END IF;\n  ELSIF NEW.scope_type = 'field' THEN\n    IF NEW.scope_id IS NULL THEN\n      RAISE EXCEPTION 'Chỉ số phạm vi lĩnh vực (field) bắt buộc phải có scope_id.';\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM public.fields WHERE id = NEW.scope_id) THEN\n      RAISE EXCEPTION 'scope_id (%) không tồn tại trong danh mục lĩnh vực (public.fields).', NEW.scope_id;\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$;\n\n-- 4.6 Hàm kiểm tra scope_id của report_analysis\nCREATE OR REPLACE FUNCTION public.validate_report_analysis_scope()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  IF NEW.scope_type = 'overview' THEN\n    IF NEW.scope_id IS NOT NULL THEN\n      RAISE EXCEPTION 'Bài phân tích tổng quan (overview) phải có scope_id là NULL.';\n    END IF;\n  ELSIF NEW.scope_type = 'unit' THEN\n    IF NEW.scope_id IS NULL THEN\n      RAISE EXCEPTION 'Bài phân tích cấp đơn vị (unit) bắt buộc phải có scope_id.';\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = NEW.scope_id) THEN\n      RAISE EXCEPTION 'scope_id (%) không tồn tại trong danh mục đơn vị (public.units).', NEW.scope_id;\n    END IF;\n  ELSIF NEW.scope_type = 'field' THEN\n    IF NEW.scope_id IS NULL THEN\n      RAISE EXCEPTION 'Bài phân tích cấp lĩnh vực (field) bắt buộc phải có scope_id.';\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM public.fields WHERE id = NEW.scope_id) THEN\n      RAISE EXCEPTION 'scope_id (%) không tồn tại trong danh mục lĩnh vực (public.fields).', NEW.scope_id;\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$$;\n\n-- 4.7 Hàm đồng bộ snapshot tên, ánh xạ field->unit, kiểm tra source_id và kiểm chứng 4 công thức\nCREATE OR REPLACE FUNCTION public.sync_report_field_statistics_columns()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nDECLARE\n  v_unit_name TEXT;\n  v_field_name TEXT;\n  v_unit_id UUID;\n  v_source_report_id UUID;\n  v_errors TEXT[] := ARRAY[]::TEXT[];\nBEGIN\n  -- 1. Kiểm tra nguồn dữ liệu source_id phải thuộc đúng kỳ báo cáo report_id\n  SELECT s.report_id INTO v_source_report_id\n  FROM public.report_sources s\n  WHERE s.id = NEW.source_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Nguồn dữ liệu source_id (%) không tồn tại trong bảng public.report_sources.', NEW.source_id;\n  END IF;\n\n  IF v_source_report_id <> NEW.report_id THEN\n    RAISE EXCEPTION 'Nguồn dữ liệu source_id (%) thuộc kỳ báo cáo (%) khác với report_id (%).', NEW.source_id, v_source_report_id, NEW.report_id;\n  END IF;\n\n  -- 2. Truy xuất ánh xạ có thẩm quyền từ public.fields và public.units (Không tin tưởng frontend/import)\n  SELECT f.name, f.unit_id, u.name \n  INTO v_field_name, v_unit_id, v_unit_name\n  FROM public.fields f\n  JOIN public.units u ON u.id = f.unit_id\n  WHERE f.id = NEW.field_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Lĩnh vực field_id (%) không tồn tại trong danh mục public.fields.', NEW.field_id;\n  END IF;\n\n  -- Ghi đè đơn vị và bản chụp tên chính xác tuyệt đối\n  NEW.unit_id := v_unit_id;\n  NEW.unit_name_snapshot := COALESCE(v_unit_name, 'Đơn vị');\n  NEW.field_name_snapshot := COALESCE(v_field_name, 'Lĩnh vực');\n\n  -- 3. Kiểm chứng 4 công thức toán học bắt buộc:\n  -- CT1: received_total = received_online + received_offline + carried_forward\n  IF NEW.received_total <> (NEW.received_online + NEW.received_offline + NEW.carried_forward) THEN\n    v_errors := array_append(v_errors, format('Sai CT1: Tổng tiếp nhận (%s) != Trực tuyến (%s) + Trực tiếp (%s) + Kỳ trước (%s)', NEW.received_total, NEW.received_online, NEW.received_offline, NEW.carried_forward));\n  END IF;\n\n  -- CT2: completed_total = completed_early + completed_on_time + completed_late\n  IF NEW.completed_total <> (NEW.completed_early + NEW.completed_on_time + NEW.completed_late) THEN\n    v_errors := array_append(v_errors, format('Sai CT2: Đã giải quyết (%s) != Trước hạn (%s) + Đúng hạn (%s) + Quá hạn (%s)', NEW.completed_total, NEW.completed_early, NEW.completed_on_time, NEW.completed_late));\n  END IF;\n\n  -- CT3: pending_total = pending_on_time + pending_late\n  IF NEW.pending_total <> (NEW.pending_on_time + NEW.pending_late) THEN\n    v_errors := array_append(v_errors, format('Sai CT3: Đang giải quyết (%s) != Trong hạn (%s) + Quá hạn (%s)', NEW.pending_total, NEW.pending_on_time, NEW.pending_late));\n  END IF;\n\n  -- CT4: received_total = completed_total + pending_total\n  IF NEW.received_total <> (NEW.completed_total + NEW.pending_total) THEN\n    v_errors := array_append(v_errors, format('Sai CT4: Tổng tiếp nhận (%s) != Đã giải quyết (%s) + Đang giải quyết (%s)', NEW.received_total, NEW.completed_total, NEW.pending_total));\n  END IF;\n\n  -- 4. Cập nhật validation_status và validation_errors\n  IF array_length(v_errors, 1) > 0 THEN\n    NEW.validation_status := 'error';\n    NEW.validation_errors := to_jsonb(v_errors);\n  ELSE\n    NEW.validation_status := 'valid';\n    NEW.validation_errors := '[]'::jsonb;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- 4.8 Hàm bảo vệ tính bất biến của số liệu khi báo cáo đã locked/archived\nCREATE OR REPLACE FUNCTION public.enforce_locked_statistics_immutability()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nDECLARE\n  v_target_report_id UUID;\n  v_report_status TEXT;\nBEGIN\n  v_target_report_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.report_id ELSE NEW.report_id END;\n  SELECT status INTO v_report_status FROM public.reports WHERE id = v_target_report_id;\n\n  IF v_report_status IN ('locked', 'archived') THEN\n    RAISE EXCEPTION 'Báo cáo này đã ở trạng thái %s. Không được phép thêm, sửa hoặc xóa số liệu thống kê.', v_report_status;\n  END IF;\n\n  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;\nEND;\n$$;\n\n-- 4.9 Hàm bảo vệ tính bất biến của nguồn dữ liệu khi báo cáo đã locked/archived\nCREATE OR REPLACE FUNCTION public.enforce_locked_sources_immutability()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nDECLARE\n  v_target_report_id UUID;\n  v_report_status TEXT;\nBEGIN\n  v_target_report_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.report_id ELSE NEW.report_id END;\n  SELECT status INTO v_report_status FROM public.reports WHERE id = v_target_report_id;\n\n  IF v_report_status IN ('locked', 'archived') THEN\n    RAISE EXCEPTION 'Báo cáo này đã ở trạng thái %s. Không được phép thêm, sửa hoặc xóa nguồn dữ liệu.', v_report_status;\n  END IF;\n\n  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;\nEND;\n$$;\n\n-- 4.10 Hàm bảo vệ tính bất biến của chỉ số khi báo cáo đã locked/archived\nCREATE OR REPLACE FUNCTION public.enforce_locked_indicators_immutability()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nDECLARE\n  v_target_report_id UUID;\n  v_report_status TEXT;\nBEGIN\n  v_target_report_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.report_id ELSE NEW.report_id END;\n  SELECT status INTO v_report_status FROM public.reports WHERE id = v_target_report_id;\n\n  IF v_report_status IN ('locked', 'archived') THEN\n    RAISE EXCEPTION 'Báo cáo này đã ở trạng thái %s. Không được phép thêm, sửa hoặc xóa chỉ số đo lường.', v_report_status;\n  END IF;\n\n  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;\nEND;\n$$;\n\n-- 4.11 Hàm bảo vệ tính bất biến của bài phân tích khi báo cáo đã locked/archived\nCREATE OR REPLACE FUNCTION public.enforce_locked_analysis_immutability()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nDECLARE\n  v_target_report_id UUID;\n  v_report_status TEXT;\nBEGIN\n  v_target_report_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.report_id ELSE NEW.report_id END;\n  SELECT status INTO v_report_status FROM public.reports WHERE id = v_target_report_id;\n\n  IF v_report_status IN ('locked', 'archived') THEN\n    RAISE EXCEPTION 'Báo cáo này đã ở trạng thái %s. Không được phép thêm, sửa hoặc xóa bài phân tích nhận xét.', v_report_status;\n  END IF;\n\n  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;\nEND;\n$$;\n\n-- 4.12 Hàm bảo vệ tính bất biến của snapshots\nCREATE OR REPLACE FUNCTION public.enforce_snapshot_immutability()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  RAISE EXCEPTION 'Bản chụp báo cáo (snapshot) là dữ liệu lịch sử bất biến, không được phép chỉnh sửa hoặc xóa.';\nEND;\n$$;\n\n-- 4.13 Hàm bảo vệ tính append-only của audit logs\nCREATE OR REPLACE FUNCTION public.enforce_audit_log_append_only()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  RAISE EXCEPTION 'Nhật ký kiểm toán (audit logs) là append-only, không cho phép chỉnh sửa hoặc xóa.';\nEND;\n$$;\n\n-- 4.14 Hàm kiểm soát vòng đời báo cáo nghiêm ngặt kết hợp phân quyền RBAC và chụp snapshot tự động\nCREATE OR REPLACE FUNCTION public.enforce_report_lifecycle_and_immutability()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public, pg_temp\nAS $$\nDECLARE\n  v_caller_role TEXT;\n  v_next_version INTEGER;\n  v_snapshot_payload JSONB;\n  v_stats_count INTEGER;\n  v_indicators_count INTEGER;\n  v_invalid_stats_count INTEGER;\nBEGIN\n  -- 1. Xử lý INSERT: Bắt buộc báo cáo mới phải bắt đầu ở trạng thái 'draft'\n  IF TG_OP = 'INSERT' THEN\n    IF NEW.status <> 'draft' THEN\n      RAISE EXCEPTION 'Báo cáo mới tạo bắt buộc phải có trạng thái ban đầu là DRAFT. Không thể tạo trực tiếp với trạng thái %s.', NEW.status;\n    END IF;\n    RETURN NEW;\n  END IF;\n\n  -- 2. Xử lý DELETE: Chặn xóa báo cáo đã locked hoặc archived\n  IF TG_OP = 'DELETE' THEN\n    IF OLD.status IN ('locked', 'archived') THEN\n      RAISE EXCEPTION 'Không thể xóa kỳ báo cáo đã ở trạng thái %s.', OLD.status;\n    END IF;\n    RETURN OLD;\n  END IF;\n\n  -- 3. Xử lý UPDATE: Bảo vệ bất biến khi đã ở LOCKED hoặc ARCHIVED\n  IF OLD.status = 'locked' AND NEW.status = 'locked' THEN\n    IF OLD.report_code <> NEW.report_code OR\n       OLD.report_name <> NEW.report_name OR\n       OLD.report_type <> NEW.report_type OR\n       OLD.period_start <> NEW.period_start OR\n       OLD.period_end <> NEW.period_end OR\n       OLD.data_as_of <> NEW.data_as_of THEN\n      RAISE EXCEPTION 'Báo cáo đã khóa (LOCKED) không được phép chỉnh sửa thông tin metadata.';\n    END IF;\n  END IF;\n\n  IF OLD.status = 'archived' AND NEW.status <> 'archived' THEN\n    RAISE EXCEPTION 'Báo cáo đã lưu trữ (ARCHIVED) là trạng thái cuối cùng, không thể chuyển đổi trạng thái khác.';\n  END IF;\n\n  -- 4. Kiểm soát chuyển đổi trạng thái tuần tự tuyệt đối & Phân quyền RBAC\n  IF OLD.status <> NEW.status THEN\n    -- A. Kiểm tra quyền thay đổi trạng thái theo Role người dùng (nếu có phiên xác thực)\n    IF auth.uid() IS NOT NULL THEN\n      v_caller_role := public.current_user_role();\n\n      IF v_caller_role = 'viewer' OR v_caller_role IS NULL THEN\n        RAISE EXCEPTION 'Người dùng có vai trò viewer không có quyền thay đổi trạng thái báo cáo.';\n      END IF;\n\n      -- data_entry không được approved, locked, archived\n      IF v_caller_role = 'data_entry' AND NEW.status IN ('approved', 'locked', 'archived') THEN\n        RAISE EXCEPTION 'Cán bộ nhập liệu (data_entry) không có quyền phê duyệt, khóa hoặc lưu trữ báo cáo.';\n      END IF;\n\n      -- approved chỉ do admin hoặc analyst\n      IF NEW.status = 'approved' AND v_caller_role NOT IN ('admin', 'analyst') THEN\n        RAISE EXCEPTION 'Chỉ lãnh đạo/quản trị viên (admin) hoặc chuyên viên phân tích (analyst) mới có quyền phê duyệt báo cáo.';\n      END IF;\n\n      -- locked & archived chỉ do admin\n      IF NEW.status IN ('locked', 'archived') AND v_caller_role <> 'admin' THEN\n        RAISE EXCEPTION 'Chỉ quản trị viên (admin) mới có quyền Khóa (locked) hoặc Lưu trữ (archived) báo cáo.';\n      END IF;\n    END IF;\n\n    -- B. Ma trận chuyển đổi trạng thái hợp lệ duy nhất:\n    -- draft -> imported\n    -- imported -> validated\n    -- validated -> submitted\n    -- submitted -> approved\n    -- approved -> locked\n    -- locked -> archived\n    IF NOT (\n      (OLD.status = 'draft' AND NEW.status = 'imported') OR\n      (OLD.status = 'imported' AND NEW.status = 'validated') OR\n      (OLD.status = 'validated' AND NEW.status = 'submitted') OR\n      (OLD.status = 'submitted' AND NEW.status = 'approved') OR\n      (OLD.status = 'approved' AND NEW.status = 'locked') OR\n      (OLD.status = 'locked' AND NEW.status = 'archived')\n    ) THEN\n      RAISE EXCEPTION 'Chuyển đổi trạng thái không hợp lệ: %s -> %s. Vòng đời bắt buộc: draft -> imported -> validated -> submitted -> approved -> locked -> archived.', OLD.status, NEW.status;\n    END IF;\n\n    -- Xử lý khi phê duyệt (approved)\n    IF NEW.status = 'approved' THEN\n      NEW.approved_at := COALESCE(NEW.approved_at, now());\n      NEW.approved_by := COALESCE(NEW.approved_by, 'Người phê duyệt');\n    END IF;\n\n    -- Xử lý khi khóa báo cáo (locked)\n    IF NEW.status = 'locked' THEN\n      -- Kiểm tra 1: Phải có ít nhất 1 bản ghi số liệu thống kê\n      SELECT count(*) INTO v_stats_count FROM public.report_field_statistics WHERE report_id = NEW.id;\n      IF v_stats_count = 0 THEN\n        RAISE EXCEPTION 'Không thể khóa báo cáo: Chưa có số liệu thống kê (report_field_statistics = 0).';\n      END IF;\n\n      -- Kiểm tra 2: Không được có số liệu bị lỗi kiểm chứng\n      SELECT count(*) INTO v_invalid_stats_count FROM public.report_field_statistics WHERE report_id = NEW.id AND validation_status = 'error';\n      IF v_invalid_stats_count > 0 THEN\n        RAISE EXCEPTION 'Không thể khóa báo cáo: Tồn tại % bản ghi số liệu vi phạm công thức toán học.', v_invalid_stats_count;\n      END IF;\n\n      -- Kiểm tra 3: Phải có ít nhất 1 chỉ số đo lường đã tính\n      SELECT count(*) INTO v_indicators_count FROM public.report_indicators WHERE report_id = NEW.id;\n      IF v_indicators_count = 0 THEN\n        RAISE EXCEPTION 'Không thể khóa báo cáo: Chưa có chỉ số đo lường (report_indicators = 0).';\n      END IF;\n\n      NEW.locked_at := COALESCE(NEW.locked_at, now());\n      NEW.locked_by := COALESCE(NEW.locked_by, 'Người khóa');\n\n      -- Tạo bản chụp snapshot toàn diện\n      SELECT COALESCE(MAX(version_number), 0) + 1 INTO v_next_version\n      FROM public.report_snapshots\n      WHERE report_id = NEW.id;\n\n      SELECT jsonb_build_object(\n        'report_metadata', jsonb_build_object(\n          'id', NEW.id,\n          'report_code', NEW.report_code,\n          'report_name', NEW.report_name,\n          'report_type', NEW.report_type,\n          'period_start', NEW.period_start,\n          'period_end', NEW.period_end,\n          'data_as_of', NEW.data_as_of,\n          'status', 'locked',\n          'created_by', NEW.created_by,\n          'approved_by', NEW.approved_by,\n          'approved_at', NEW.approved_at,\n          'locked_by', NEW.locked_by,\n          'locked_at', NEW.locked_at\n        ),\n        'sources', (\n          SELECT COALESCE(jsonb_agg(row_to_json(s)), '[]'::jsonb) \n          FROM public.report_sources s \n          WHERE s.report_id = NEW.id\n        ),\n        'field_statistics', (\n          SELECT COALESCE(jsonb_agg(row_to_json(st)), '[]'::jsonb) \n          FROM public.report_field_statistics st \n          WHERE st.report_id = NEW.id\n        ),\n        'field_unit_mapping', (\n          SELECT COALESCE(jsonb_agg(jsonb_build_object(\n            'unit_id', u.id,\n            'unit_code', u.code,\n            'unit_name', u.name,\n            'fields', (\n              SELECT COALESCE(jsonb_agg(row_to_json(f)), '[]'::jsonb)\n              FROM public.fields f\n              WHERE f.unit_id = u.id\n            )\n          )), '[]'::jsonb)\n          FROM public.units u\n        ),\n        'indicators', (\n          SELECT COALESCE(jsonb_agg(row_to_json(i)), '[]'::jsonb) \n          FROM public.report_indicators i \n          WHERE i.report_id = NEW.id\n        ),\n        'analysis', (\n          SELECT COALESCE(jsonb_agg(row_to_json(a)), '[]'::jsonb) \n          FROM public.report_analysis a \n          WHERE a.report_id = NEW.id\n        ),\n        'captured_at', now()\n      ) INTO v_snapshot_payload;\n\n      INSERT INTO public.report_snapshots (\n        id,\n        report_id,\n        version_number,\n        snapshot_json,\n        created_by,\n        reason,\n        created_at\n      ) VALUES (\n        gen_random_uuid(),\n        NEW.id,\n        v_next_version,\n        v_snapshot_payload,\n        COALESCE(NEW.locked_by, NEW.created_by, 'Hệ thống'),\n        'Đóng băng bản sao toàn diện khi chuyển trạng thái sang Khóa (LOCKED)',\n        now()\n      ) ON CONFLICT (report_id, version_number) DO NOTHING;\n    END IF;\n\n    -- Xử lý khi chuyển sang lưu trữ (archived)\n    IF NEW.status = 'archived' THEN\n      NEW.archived_at := COALESCE(NEW.archived_at, now());\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$;\n\n-- ==============================================================================\n-- 5. GẮN TRIGGERS VÀO CÁC BẢNG\n-- ==============================================================================\n\n-- Triggers cập nhật updated_at\nDROP TRIGGER IF EXISTS trg_units_updated_at ON public.units;\nCREATE TRIGGER trg_units_updated_at BEFORE UPDATE ON public.units FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_timestamp();\n\nDROP TRIGGER IF EXISTS trg_profiles_updated_at ON public.profiles;\nCREATE TRIGGER trg_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_timestamp();\n\nDROP TRIGGER IF EXISTS trg_fields_updated_at ON public.fields;\nCREATE TRIGGER trg_fields_updated_at BEFORE UPDATE ON public.fields FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_timestamp();\n\nDROP TRIGGER IF EXISTS trg_reports_updated_at ON public.reports;\nCREATE TRIGGER trg_reports_updated_at BEFORE UPDATE ON public.reports FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_timestamp();\n\nDROP TRIGGER IF EXISTS trg_report_sources_updated_at ON public.report_sources;\nCREATE TRIGGER trg_report_sources_updated_at BEFORE UPDATE ON public.report_sources FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_timestamp();\n\nDROP TRIGGER IF EXISTS trg_report_field_statistics_updated_at ON public.report_field_statistics;\nCREATE TRIGGER trg_report_field_statistics_updated_at BEFORE UPDATE ON public.report_field_statistics FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_timestamp();\n\nDROP TRIGGER IF EXISTS trg_indicator_definitions_updated_at ON public.indicator_definitions;\nCREATE TRIGGER trg_indicator_definitions_updated_at BEFORE UPDATE ON public.indicator_definitions FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_timestamp();\n\nDROP TRIGGER IF EXISTS trg_report_indicators_updated_at ON public.report_indicators;\nCREATE TRIGGER trg_report_indicators_updated_at BEFORE UPDATE ON public.report_indicators FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_timestamp();\n\nDROP TRIGGER IF EXISTS trg_report_analysis_updated_at ON public.report_analysis;\nCREATE TRIGGER trg_report_analysis_updated_at BEFORE UPDATE ON public.report_analysis FOR EACH ROW EXECUTE FUNCTION public.set_updated_at_timestamp();\n\n-- Trigger bảo vệ chống Privilege Escalation trên profiles (cả INSERT và UPDATE)\nDROP TRIGGER IF EXISTS trg_protect_profiles_privilege_escalation ON public.profiles;\nCREATE TRIGGER trg_protect_profiles_privilege_escalation BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_profiles_privilege_escalation();\n\n-- Trigger kiểm tra scope_id của report_indicators & report_analysis\nDROP TRIGGER IF EXISTS trg_validate_report_indicator_scope ON public.report_indicators;\nCREATE TRIGGER trg_validate_report_indicator_scope BEFORE INSERT OR UPDATE ON public.report_indicators FOR EACH ROW EXECUTE FUNCTION public.validate_report_indicator_scope();\n\nDROP TRIGGER IF EXISTS trg_validate_report_analysis_scope ON public.report_analysis;\nCREATE TRIGGER trg_validate_report_analysis_scope BEFORE INSERT OR UPDATE ON public.report_analysis FOR EACH ROW EXECUTE FUNCTION public.validate_report_analysis_scope();\n\n-- Trigger đồng bộ snapshot tên đơn vị/lĩnh vực & kiểm chứng 4 công thức cho bảng thống kê\nDROP TRIGGER IF EXISTS trg_report_field_statistics_sync ON public.report_field_statistics;\nCREATE TRIGGER trg_report_field_statistics_sync BEFORE INSERT OR UPDATE ON public.report_field_statistics FOR EACH ROW EXECUTE FUNCTION public.sync_report_field_statistics_columns();\n\n-- Triggers bảo vệ tính bất biến khi báo cáo bị khóa\nDROP TRIGGER IF EXISTS trg_statistics_lock_guard ON public.report_field_statistics;\nCREATE TRIGGER trg_statistics_lock_guard BEFORE INSERT OR UPDATE OR DELETE ON public.report_field_statistics FOR EACH ROW EXECUTE FUNCTION public.enforce_locked_statistics_immutability();\n\nDROP TRIGGER IF EXISTS trg_sources_lock_guard ON public.report_sources;\nCREATE TRIGGER trg_sources_lock_guard BEFORE INSERT OR UPDATE OR DELETE ON public.report_sources FOR EACH ROW EXECUTE FUNCTION public.enforce_locked_sources_immutability();\n\nDROP TRIGGER IF EXISTS trg_indicators_lock_guard ON public.report_indicators;\nCREATE TRIGGER trg_indicators_lock_guard BEFORE INSERT OR UPDATE OR DELETE ON public.report_indicators FOR EACH ROW EXECUTE FUNCTION public.enforce_locked_indicators_immutability();\n\nDROP TRIGGER IF EXISTS trg_analysis_lock_guard ON public.report_analysis;\nCREATE TRIGGER trg_analysis_lock_guard BEFORE INSERT OR UPDATE OR DELETE ON public.report_analysis FOR EACH ROW EXECUTE FUNCTION public.enforce_locked_analysis_immutability();\n\n-- Trigger bảo vệ snapshots & audit logs\nDROP TRIGGER IF EXISTS trg_snapshots_immutability ON public.report_snapshots;\nCREATE TRIGGER trg_snapshots_immutability BEFORE UPDATE OR DELETE ON public.report_snapshots FOR EACH ROW EXECUTE FUNCTION public.enforce_snapshot_immutability();\n\nDROP TRIGGER IF EXISTS trg_audit_logs_append_only ON public.audit_logs;\nCREATE TRIGGER trg_audit_logs_append_only BEFORE UPDATE OR DELETE ON public.audit_logs FOR EACH ROW EXECUTE FUNCTION public.enforce_audit_log_append_only();\n\n-- Trigger vòng đời báo cáo (áp dụng cả INSERT và UPDATE/DELETE)\nDROP TRIGGER IF EXISTS trg_reports_lifecycle ON public.reports;\nCREATE TRIGGER trg_reports_lifecycle BEFORE INSERT OR UPDATE OR DELETE ON public.reports FOR EACH ROW EXECUTE FUNCTION public.enforce_report_lifecycle_and_immutability();\n\n-- ==============================================================================\n-- 6. TẠO INDEXES TỐI ƯU TRUY VẤN\n-- ==============================================================================\nCREATE INDEX IF NOT EXISTS idx_fields_unit_id ON public.fields(unit_id);\nCREATE INDEX IF NOT EXISTS idx_reports_period ON public.reports(period_start DESC, period_end DESC);\nCREATE INDEX IF NOT EXISTS idx_reports_status ON public.reports(status);\nCREATE INDEX IF NOT EXISTS idx_report_sources_report_id ON public.report_sources(report_id);\nCREATE INDEX IF NOT EXISTS idx_stats_report_id ON public.report_field_statistics(report_id);\nCREATE INDEX IF NOT EXISTS idx_stats_source_id ON public.report_field_statistics(source_id);\nCREATE INDEX IF NOT EXISTS idx_stats_field_id ON public.report_field_statistics(field_id);\nCREATE INDEX IF NOT EXISTS idx_stats_unit_id ON public.report_field_statistics(unit_id);\nCREATE INDEX IF NOT EXISTS idx_indicators_report_id ON public.report_indicators(report_id);\nCREATE INDEX IF NOT EXISTS idx_analysis_report_id ON public.report_analysis(report_id);\nCREATE INDEX IF NOT EXISTS idx_snapshots_report_id ON public.report_snapshots(report_id);\nCREATE INDEX IF NOT EXISTS idx_audit_logs_created_at ON public.audit_logs(created_at DESC);\n\n-- ==============================================================================\n-- 7. CẤU HÌNH ROW LEVEL SECURITY (RLS) & POLICIES (AUTHENTICATED ONLY)\n-- ==============================================================================\nALTER TABLE public.units ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.fields ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.reports ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.report_sources ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.report_field_statistics ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.indicator_definitions ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.report_indicators ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.report_analysis ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.report_snapshots ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;\n\n-- 1. Policies cho units\nDROP POLICY IF EXISTS \"units_select_policy\" ON public.units;\nCREATE POLICY \"units_select_policy\" ON public.units FOR SELECT TO authenticated USING (true);\n\nDROP POLICY IF EXISTS \"units_insert_policy\" ON public.units;\nCREATE POLICY \"units_insert_policy\" ON public.units FOR INSERT TO authenticated WITH CHECK (public.current_user_role() = 'admin');\n\nDROP POLICY IF EXISTS \"units_update_policy\" ON public.units;\nCREATE POLICY \"units_update_policy\" ON public.units FOR UPDATE TO authenticated USING (public.current_user_role() = 'admin') WITH CHECK (public.current_user_role() = 'admin');\n\nDROP POLICY IF EXISTS \"units_delete_policy\" ON public.units;\nCREATE POLICY \"units_delete_policy\" ON public.units FOR DELETE TO authenticated USING (public.current_user_role() = 'admin');\n\n-- 2. Policies cho profiles (Người dùng tự tạo/sửa thông tin cơ bản của mình; Trigger bảo vệ quyền role)\nDROP POLICY IF EXISTS \"profiles_select_policy\" ON public.profiles;\nCREATE POLICY \"profiles_select_policy\" ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id OR public.current_user_role() = 'admin');\n\nDROP POLICY IF EXISTS \"profiles_insert_policy\" ON public.profiles;\nCREATE POLICY \"profiles_insert_policy\" ON public.profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = id OR public.current_user_role() = 'admin');\n\nDROP POLICY IF EXISTS \"profiles_update_policy\" ON public.profiles;\nCREATE POLICY \"profiles_update_policy\" ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id OR public.current_user_role() = 'admin') WITH CHECK (auth.uid() = id OR public.current_user_role() = 'admin');\n\nDROP POLICY IF EXISTS \"profiles_delete_policy\" ON public.profiles;\nCREATE POLICY \"profiles_delete_policy\" ON public.profiles FOR DELETE TO authenticated USING (public.current_user_role() = 'admin');\n\n-- 3. Policies cho fields\nDROP POLICY IF EXISTS \"fields_select_policy\" ON public.fields;\nCREATE POLICY \"fields_select_policy\" ON public.fields FOR SELECT TO authenticated USING (true);\n\nDROP POLICY IF EXISTS \"fields_insert_policy\" ON public.fields;\nCREATE POLICY \"fields_insert_policy\" ON public.fields FOR INSERT TO authenticated WITH CHECK (public.current_user_role() = 'admin');\n\nDROP POLICY IF EXISTS \"fields_update_policy\" ON public.fields;\nCREATE POLICY \"fields_update_policy\" ON public.fields FOR UPDATE TO authenticated USING (public.current_user_role() = 'admin') WITH CHECK (public.current_user_role() = 'admin');\n\nDROP POLICY IF EXISTS \"fields_delete_policy\" ON public.fields;\nCREATE POLICY \"fields_delete_policy\" ON public.fields FOR DELETE TO authenticated USING (public.current_user_role() = 'admin');\n\n-- 4. Policies cho reports\nDROP POLICY IF EXISTS \"reports_select_policy\" ON public.reports;\nCREATE POLICY \"reports_select_policy\" ON public.reports FOR SELECT TO authenticated USING (true);\n\nDROP POLICY IF EXISTS \"reports_insert_policy\" ON public.reports;\nCREATE POLICY \"reports_insert_policy\" ON public.reports FOR INSERT TO authenticated WITH CHECK (public.current_user_role() IN ('admin', 'analyst', 'data_entry'));\n\nDROP POLICY IF EXISTS \"reports_update_policy\" ON public.reports;\nCREATE POLICY \"reports_update_policy\" ON public.reports FOR UPDATE TO authenticated USING (public.current_user_role() IN ('admin', 'analyst', 'data_entry')) WITH CHECK (public.current_user_role() IN ('admin', 'analyst', 'data_entry'));\n\nDROP POLICY IF EXISTS \"reports_delete_policy\" ON public.reports;\nCREATE POLICY \"reports_delete_policy\" ON public.reports FOR DELETE TO authenticated USING (public.current_user_role() = 'admin');\n\n-- 5. Policies cho report_sources\nDROP POLICY IF EXISTS \"report_sources_select_policy\" ON public.report_sources;\nCREATE POLICY \"report_sources_select_policy\" ON public.report_sources FOR SELECT TO authenticated USING (true);\n\nDROP POLICY IF EXISTS \"report_sources_insert_policy\" ON public.report_sources;\nCREATE POLICY \"report_sources_insert_policy\" ON public.report_sources FOR INSERT TO authenticated WITH CHECK (public.current_user_role() IN ('admin', 'analyst', 'data_entry'));\n\nDROP POLICY IF EXISTS \"report_sources_update_policy\" ON public.report_sources;\nCREATE POLICY \"report_sources_update_policy\" ON public.report_sources FOR UPDATE TO authenticated USING (public.current_user_role() IN ('admin', 'analyst', 'data_entry')) WITH CHECK (public.current_user_role() IN ('admin', 'analyst', 'data_entry'));\n\nDROP POLICY IF EXISTS \"report_sources_delete_policy\" ON public.report_sources;\nCREATE POLICY \"report_sources_delete_policy\" ON public.report_sources FOR DELETE TO authenticated USING (public.current_user_role() = 'admin');\n\n-- 6. Policies cho report_field_statistics\nDROP POLICY IF EXISTS \"stats_select_policy\" ON public.report_field_statistics;\nCREATE POLICY \"stats_select_policy\" ON public.report_field_statistics FOR SELECT TO authenticated USING (true);\n\nDROP POLICY IF EXISTS \"stats_insert_policy\" ON public.report_field_statistics;\nCREATE POLICY \"stats_insert_policy\" ON public.report_field_statistics FOR INSERT TO authenticated WITH CHECK (public.current_user_role() IN ('admin', 'analyst', 'data_entry'));\n\nDROP POLICY IF EXISTS \"stats_update_policy\" ON public.report_field_statistics;\nCREATE POLICY \"stats_update_policy\" ON public.report_field_statistics FOR UPDATE TO authenticated USING (public.current_user_role() IN ('admin', 'analyst', 'data_entry')) WITH CHECK (public.current_user_role() IN ('admin', 'analyst', 'data_entry'));\n\nDROP POLICY IF EXISTS \"stats_delete_policy\" ON public.report_field_statistics;\nCREATE POLICY \"stats_delete_policy\" ON public.report_field_statistics FOR DELETE TO authenticated USING (public.current_user_role() = 'admin');\n\n-- 7. Policies cho indicator_definitions\nDROP POLICY IF EXISTS \"indicators_def_select_policy\" ON public.indicator_definitions;\nCREATE POLICY \"indicators_def_select_policy\" ON public.indicator_definitions FOR SELECT TO authenticated USING (true);\n\nDROP POLICY IF EXISTS \"indicators_def_insert_policy\" ON public.indicator_definitions;\nCREATE POLICY \"indicators_def_insert_policy\" ON public.indicator_definitions FOR INSERT TO authenticated WITH CHECK (public.current_user_role() = 'admin');\n\nDROP POLICY IF EXISTS \"indicators_def_update_policy\" ON public.indicator_definitions;\nCREATE POLICY \"indicators_def_update_policy\" ON public.indicator_definitions FOR UPDATE TO authenticated USING (public.current_user_role() = 'admin') WITH CHECK (public.current_user_role() = 'admin');\n\nDROP POLICY IF EXISTS \"indicators_def_delete_policy\" ON public.indicator_definitions;\nCREATE POLICY \"indicators_def_delete_policy\" ON public.indicator_definitions FOR DELETE TO authenticated USING (public.current_user_role() = 'admin');\n\n-- 8. Policies cho report_indicators\nDROP POLICY IF EXISTS \"report_indicators_select_policy\" ON public.report_indicators;\nCREATE POLICY \"report_indicators_select_policy\" ON public.report_indicators FOR SELECT TO authenticated USING (true);\n\nDROP POLICY IF EXISTS \"report_indicators_insert_policy\" ON public.report_indicators;\nCREATE POLICY \"report_indicators_insert_policy\" ON public.report_indicators FOR INSERT TO authenticated WITH CHECK (public.current_user_role() IN ('admin', 'analyst'));\n\nDROP POLICY IF EXISTS \"report_indicators_update_policy\" ON public.report_indicators;\nCREATE POLICY \"report_indicators_update_policy\" ON public.report_indicators FOR UPDATE TO authenticated USING (public.current_user_role() IN ('admin', 'analyst')) WITH CHECK (public.current_user_role() IN ('admin', 'analyst'));\n\nDROP POLICY IF EXISTS \"report_indicators_delete_policy\" ON public.report_indicators;\nCREATE POLICY \"report_indicators_delete_policy\" ON public.report_indicators FOR DELETE TO authenticated USING (public.current_user_role() = 'admin');\n\n-- 9. Policies cho report_analysis\nDROP POLICY IF EXISTS \"analysis_select_policy\" ON public.report_analysis;\nCREATE POLICY \"analysis_select_policy\" ON public.report_analysis FOR SELECT TO authenticated USING (true);\n\nDROP POLICY IF EXISTS \"analysis_insert_policy\" ON public.report_analysis;\nCREATE POLICY \"analysis_insert_policy\" ON public.report_analysis FOR INSERT TO authenticated WITH CHECK (public.current_user_role() IN ('admin', 'analyst'));\n\nDROP POLICY IF EXISTS \"analysis_update_policy\" ON public.report_analysis;\nCREATE POLICY \"analysis_update_policy\" ON public.report_analysis FOR UPDATE TO authenticated USING (public.current_user_role() IN ('admin', 'analyst')) WITH CHECK (public.current_user_role() IN ('admin', 'analyst'));\n\nDROP POLICY IF EXISTS \"analysis_delete_policy\" ON public.report_analysis;\nCREATE POLICY \"analysis_delete_policy\" ON public.report_analysis FOR DELETE TO authenticated USING (public.current_user_role() = 'admin');\n\n-- 10. Policies cho report_snapshots (Không có policy INSERT cho client; chỉ sinh tự động qua SECURITY DEFINER)\nDROP POLICY IF EXISTS \"snapshots_select_policy\" ON public.report_snapshots;\nCREATE POLICY \"snapshots_select_policy\" ON public.report_snapshots FOR SELECT TO authenticated USING (true);\n\nDROP POLICY IF EXISTS \"snapshots_insert_policy\" ON public.report_snapshots;\n\n-- 11. Policies cho audit_logs (Không có policy INSERT cho client; chỉ ghi qua function write_audit_log)\nDROP POLICY IF EXISTS \"audit_logs_select_policy\" ON public.audit_logs;\nCREATE POLICY \"audit_logs_select_policy\" ON public.audit_logs FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);\n\nDROP POLICY IF EXISTS \"audit_logs_insert_policy\" ON public.audit_logs;\n";

export const SEED_DATA_SQL = "-- ==============================================================================\n-- HỆ THỐNG QUẢN LÝ BÁO CÁO VÀ PHÂN TÍCH CHỈ SỐ THỦ TỤC HÀNH CHÍNH (TTHC)\n-- TẬP TIN 002: DỮ LIỆU MẪU KIỂM THỬ VÀ XÁC THỰC TOÀN DIỆN (DEMO SEED & VERIFICATION)\n-- PHIÊN BẢN: 4.0 ENTERPRISE HARDENED & DYNAMIC METRICS\n-- ĐẶC TÍNH: 100% RE-RUNNABLE / TÍNH TOÁN ĐỘNG TỰ THÂN TỪ 15 FIELDS / ZERO HARCODING\n-- ==============================================================================\n\n-- ==============================================================================\n-- 1. DỌN DẸP DỮ LIỆU DEMO CŨ BẰNG CƠ CHẾ DÀNH RIÊNG CHO MIGRATION/SEED\n-- ==============================================================================\n-- Tạm thời ngắt trigger bảo vệ chỉ phục vụ dọn dẹp các bản ghi DEMO đã khóa trong phiên chạy migration\nALTER TABLE public.report_field_statistics DISABLE TRIGGER trg_statistics_lock_guard;\nALTER TABLE public.report_sources DISABLE TRIGGER trg_sources_lock_guard;\nALTER TABLE public.report_indicators DISABLE TRIGGER trg_indicators_lock_guard;\nALTER TABLE public.report_analysis DISABLE TRIGGER trg_analysis_lock_guard;\nALTER TABLE public.report_snapshots DISABLE TRIGGER trg_snapshots_immutability;\nALTER TABLE public.reports DISABLE TRIGGER trg_reports_lifecycle;\n\n-- Dọn dẹp sạch sẽ toàn bộ các bản ghi DEMO cũ (idempotent)\nDELETE FROM public.report_snapshots WHERE report_id IN (SELECT id FROM public.reports WHERE report_code LIKE 'DEMO-%');\nDELETE FROM public.report_analysis WHERE report_id IN (SELECT id FROM public.reports WHERE report_code LIKE 'DEMO-%');\nDELETE FROM public.report_indicators WHERE report_id IN (SELECT id FROM public.reports WHERE report_code LIKE 'DEMO-%');\nDELETE FROM public.report_field_statistics WHERE report_id IN (SELECT id FROM public.reports WHERE report_code LIKE 'DEMO-%');\nDELETE FROM public.report_sources WHERE report_id IN (SELECT id FROM public.reports WHERE report_code LIKE 'DEMO-%');\nDELETE FROM public.reports WHERE report_code LIKE 'DEMO-%';\n\n-- Kích hoạt lại toàn bộ trigger bảo vệ dữ liệu sản xuất\nALTER TABLE public.reports ENABLE TRIGGER trg_reports_lifecycle;\nALTER TABLE public.report_snapshots ENABLE TRIGGER trg_snapshots_immutability;\nALTER TABLE public.report_analysis ENABLE TRIGGER trg_analysis_lock_guard;\nALTER TABLE public.report_indicators ENABLE TRIGGER trg_indicators_lock_guard;\nALTER TABLE public.report_sources ENABLE TRIGGER trg_sources_lock_guard;\nALTER TABLE public.report_field_statistics ENABLE TRIGGER trg_statistics_lock_guard;\n\n-- ==============================================================================\n-- 2. KHỞI TẠO DANH MỤC 3 ĐƠN VỊ HÀNH CHÍNH\n-- ==============================================================================\nINSERT INTO public.units (id, code, name, display_order, active)\nVALUES\n  ('u1000000-0000-0000-0000-000000000001', 'VP', 'Văn phòng HĐND & UBND', 1, true),\n  ('u1000000-0000-0000-0000-000000000002', 'PKT', 'Phòng Kinh tế', 2, true),\n  ('u1000000-0000-0000-0000-000000000003', 'PVHXH', 'Phòng Văn hóa - Xã hội', 3, true)\nON CONFLICT (id) DO UPDATE SET\n  code = EXCLUDED.code,\n  name = EXCLUDED.name,\n  display_order = EXCLUDED.display_order,\n  active = EXCLUDED.active;\n\n-- ==============================================================================\n-- 3. KHỞI TẠO DANH MỤC 15 LĨNH VỰC TTHC VỚI ÁNH XẠ ĐƠN VỊ 1-1 TUYỆT ĐỐI\n-- ==============================================================================\nINSERT INTO public.fields (id, code, name, unit_id, display_order, active)\nVALUES\n  -- Thuộc Văn phòng HĐND & UBND (3 lĩnh vực)\n  ('f1000000-0000-0000-0000-000000000001', 'CT', 'Chứng thực', 'u1000000-0000-0000-0000-000000000001', 1, true),\n  ('f1000000-0000-0000-0000-000000000002', 'HT', 'Hộ tịch', 'u1000000-0000-0000-0000-000000000001', 2, true),\n  ('f1000000-0000-0000-0000-000000000003', 'PLP', 'Phí, lệ phí', 'u1000000-0000-0000-0000-000000000001', 3, true),\n\n  -- Thuộc Phòng Kinh tế (7 lĩnh vực)\n  ('f1000000-0000-0000-0000-000000000004', 'ATTP', 'An toàn thực phẩm', 'u1000000-0000-0000-0000-000000000002', 4, true),\n  ('f1000000-0000-0000-0000-000000000005', 'HHDT', 'Hàng hải và đường thủy nội địa', 'u1000000-0000-0000-0000-000000000002', 5, true),\n  ('f1000000-0000-0000-0000-000000000006', 'QH', 'Quy hoạch đô thị và nông thôn', 'u1000000-0000-0000-0000-000000000002', 6, true),\n  ('f1000000-0000-0000-0000-000000000007', 'XD', 'Hoạt động xây dựng', 'u1000000-0000-0000-0000-000000000002', 7, true),\n  ('f1000000-0000-0000-0000-000000000008', 'LTHH', 'Lưu thông hàng hóa trong nước', 'u1000000-0000-0000-0000-000000000002', 8, true),\n  ('f1000000-0000-0000-0000-000000000009', 'DD', 'Đất đai', 'u1000000-0000-0000-0000-000000000002', 9, true),\n  ('f1000000-0000-0000-0000-000000000010', 'TS', 'Thủy sản', 'u1000000-0000-0000-0000-000000000002', 10, true),\n\n  -- Thuộc Phòng Văn hóa - Xã hội (5 lĩnh vực)\n  ('f1000000-0000-0000-0000-000000000011', 'BTXH', 'Bảo trợ xã hội', 'u1000000-0000-0000-0000-000000000003', 11, true),\n  ('f1000000-0000-0000-0000-000000000012', 'GDMN', 'Giáo dục mầm non', 'u1000000-0000-0000-0000-000000000003', 12, true),\n  ('f1000000-0000-0000-0000-000000000013', 'GDTH', 'Giáo dục trung học', 'u1000000-0000-0000-0000-000000000003', 13, true),\n  ('f1000000-0000-0000-0000-000000000014', 'NCC', 'Người có công', 'u1000000-0000-0000-0000-000000000003', 14, true),\n  ('f1000000-0000-0000-0000-000000000015', 'CS', 'Chính sách', 'u1000000-0000-0000-0000-000000000003', 15, true)\nON CONFLICT (id) DO UPDATE SET\n  code = EXCLUDED.code,\n  name = EXCLUDED.name,\n  unit_id = EXCLUDED.unit_id,\n  display_order = EXCLUDED.display_order,\n  active = EXCLUDED.active;\n\n-- ==============================================================================\n-- 4. KHỞI TẠO TỪ ĐIỂN 3 CHỈ SỐ ĐO LƯỜNG CHUẨN\n-- ==============================================================================\nINSERT INTO public.indicator_definitions (id, code, name, formula_key, unit_measure, target_value, description, display_order, active)\nVALUES\n  ('d1000000-0000-0000-0000-000000000001', 'ONLINE_RATE', 'Tỷ lệ nộp hồ sơ trực tuyến', 'SUM(received_online) / SUM(received_online + received_offline) * 100', '%', 80.00, 'Tỷ lệ phần trăm hồ sơ tiếp nhận trực tuyến trên tổng số hồ sơ phát sinh mới trong kỳ.', 1, true),\n  ('d1000000-0000-0000-0000-000000000002', 'ON_TIME_COMPLETION_RATE', 'Tỷ lệ giải quyết đúng và trước hạn', 'SUM(completed_early + completed_on_time) / SUM(completed_total) * 100', '%', 98.00, 'Tỷ lệ phần trăm hồ sơ được giải quyết trước hạn và đúng hạn trên tổng số hồ sơ đã giải quyết.', 2, true),\n  ('d1000000-0000-0000-0000-000000000003', 'OVERDUE_COMPLETION_RATE', 'Tỷ lệ giải quyết quá hạn', 'SUM(completed_late) / SUM(completed_total) * 100', '%', 2.00, 'Tỷ lệ phần trăm hồ sơ giải quyết trễ hạn trên tổng số hồ sơ đã giải quyết.', 3, true)\nON CONFLICT (id) DO UPDATE SET\n  code = EXCLUDED.code,\n  name = EXCLUDED.name,\n  formula_key = EXCLUDED.formula_key,\n  unit_measure = EXCLUDED.unit_measure,\n  target_value = EXCLUDED.target_value,\n  description = EXCLUDED.description,\n  display_order = EXCLUDED.display_order,\n  active = EXCLUDED.active;\n\n-- ==============================================================================\n-- 5. SEED KỲ BÁO CÁO 1 (DEMO-BC-2026-01): ĐI ĐÚNG VÒNG ĐỜI VÀ KHÓA TỰ ĐỘNG\n-- ==============================================================================\n\n-- 5.1 Bước 1: Tạo báo cáo với trạng thái bắt buộc ban đầu là 'draft'\nINSERT INTO public.reports (\n  id, report_code, report_name, report_type, \n  period_start, period_end, data_as_of, \n  status, created_by, notes\n) VALUES (\n  'b1000000-0000-0000-0000-000000000001',\n  'DEMO-BC-2026-01',\n  'Báo cáo TTHC Tháng 01/2026 (Chính thức)',\n  'monthly',\n  '2026-01-01',\n  '2026-01-31',\n  '2026-01-31 23:59:59+07',\n  'draft',\n  'Cán bộ Thống kê',\n  'Số liệu toàn diện Tháng 01/2026 đã thu thập đầy đủ.'\n);\n\n-- 5.2 Khởi tạo 1 nguồn dữ liệu duy nhất chứa trọn vẹn 15 lĩnh vực\nINSERT INTO public.report_sources (\n  id, report_id, source_type, source_name, original_filename, uploaded_by, import_status, notes\n) VALUES (\n  's1000000-0000-0000-0000-000000000001',\n  'b1000000-0000-0000-0000-000000000001',\n  'system',\n  'Trên Hệ thống các Bộ',\n  'he_thong_cac_bo_t1_2026.xlsx',\n  'Cán bộ Thống kê',\n  'completed',\n  'Dữ liệu tổng hợp từ hệ thống bộ ngành'\n);\n\n-- 5.3 Khởi tạo 15 bản ghi thống kê chi tiết theo đúng các giá trị thực tế 100%:\n-- Tổng tiếp nhận: 808 (Trực tuyến: 657, Trực tiếp: 137, Kỳ trước chuyển qua: 14) -> Tổng mới: 794\n-- Tổng đã giải quyết: 776 (Trước hạn: 471, Đúng hạn: 304, Quá hạn: 1)\n-- Tổng đang giải quyết: 32 (Trong hạn: 32, Quá hạn: 0)\n-- CT1: 808 = 657 + 137 + 14\n-- CT2: 776 = 471 + 304 + 1\n-- CT3: 32 = 32 + 0\n-- CT4: 808 = 776 + 32\nINSERT INTO public.report_field_statistics (\n  report_id, source_id, field_id, field_name_snapshot, unit_id, unit_name_snapshot,\n  received_total, received_online, received_offline, carried_forward,\n  completed_total, completed_early, completed_on_time, completed_late,\n  pending_total, pending_on_time, pending_late, validation_status, notes\n) VALUES\n  -- Văn phòng HĐND & UBND (3 lĩnh vực)\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000001', 'Chứng thực', 'u1000000-0000-0000-0000-000000000001', 'Văn phòng HĐND & UBND', 320, 280, 40, 0, 315, 210, 105, 0, 5, 5, 0, 'valid', 'Chứng thực bản sao điện tử'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000002', 'Hộ tịch', 'u1000000-0000-0000-0000-000000000001', 'Văn phòng HĐND & UBND', 145, 121, 21, 3, 138, 80, 58, 0, 7, 7, 0, 'valid', 'Đăng ký khai sinh liên thông'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000003', 'Phí, lệ phí', 'u1000000-0000-0000-0000-000000000001', 'Văn phòng HĐND & UBND', 30, 25, 5, 0, 30, 15, 15, 0, 0, 0, 0, 'valid', 'Thu phí lệ phí trực tuyến'),\n\n  -- Phòng Kinh tế (7 lĩnh vực)\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000004', 'An toàn thực phẩm', 'u1000000-0000-0000-0000-000000000002', 'Phòng Kinh tế', 25, 20, 5, 0, 24, 12, 12, 0, 1, 1, 0, 'valid', 'Cấp giấy chứng nhận ATTP'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000005', 'Hàng hải và đường thủy nội địa', 'u1000000-0000-0000-0000-000000000002', 'Phòng Kinh tế', 12, 8, 4, 0, 11, 6, 5, 0, 1, 1, 0, 'valid', 'Đăng ký phương tiện thủy nội địa'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000006', 'Quy hoạch đô thị và nông thôn', 'u1000000-0000-0000-0000-000000000002', 'Phòng Kinh tế', 18, 14, 3, 1, 16, 8, 8, 0, 2, 2, 0, 'valid', 'Cung cấp thông tin quy hoạch'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000007', 'Hoạt động xây dựng', 'u1000000-0000-0000-0000-000000000002', 'Phòng Kinh tế', 60, 45, 12, 3, 56, 32, 24, 0, 4, 4, 0, 'valid', 'Cấp giấy phép xây dựng'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000008', 'Lưu thông hàng hóa trong nước', 'u1000000-0000-0000-0000-000000000002', 'Phòng Kinh tế', 16, 12, 4, 0, 16, 10, 6, 0, 0, 0, 0, 'valid', 'Thông báo hoạt động khuyến mại'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000009', 'Đất đai', 'u1000000-0000-0000-0000-000000000002', 'Phòng Kinh tế', 75, 50, 20, 5, 68, 35, 32, 1, 7, 7, 0, 'valid', 'Đăng ký biến động quyền sử dụng đất (01 hồ sơ giải quyết trễ hạn)'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000010', 'Thủy sản', 'u1000000-0000-0000-0000-000000000002', 'Phòng Kinh tế', 8, 6, 2, 0, 8, 4, 4, 0, 0, 0, 0, 'valid', 'Cấp giấy phép khai thác thủy sản'),\n\n  -- Phòng Văn hóa - Xã hội (5 lĩnh vực)\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000011', 'Bảo trợ xã hội', 'u1000000-0000-0000-0000-000000000003', 'Phòng Văn hóa - Xã hội', 35, 26, 8, 1, 33, 20, 13, 0, 2, 2, 0, 'valid', 'Trợ cấp xã hội hàng tháng'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000012', 'Giáo dục mầm non', 'u1000000-0000-0000-0000-000000000003', 'Phòng Văn hóa - Xã hội', 14, 11, 3, 0, 14, 10, 4, 0, 0, 0, 0, 'valid', 'Thành lập nhóm trẻ tư thục'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000013', 'Giáo dục trung học', 'u1000000-0000-0000-0000-000000000003', 'Phòng Văn hóa - Xã hội', 10, 8, 2, 0, 10, 7, 3, 0, 0, 0, 0, 'valid', 'Chuyển trường THCS'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000014', 'Người có công', 'u1000000-0000-0000-0000-000000000003', 'Phòng Văn hóa - Xã hội', 22, 17, 4, 1, 20, 13, 7, 0, 2, 2, 0, 'valid', 'Chế độ người có công'),\n  ('b1000000-0000-0000-0000-000000000001', 's1000000-0000-0000-0000-000000000001', 'f1000000-0000-0000-0000-000000000015', 'Chính sách', 'u1000000-0000-0000-0000-000000000003', 'Phòng Văn hóa - Xã hội', 18, 14, 4, 0, 17, 9, 8, 0, 1, 1, 0, 'valid', 'Chính sách việc làm');\n\n-- 5.4 Bước 2: Chuyển sang 'imported'\nUPDATE public.reports SET status = 'imported' WHERE id = 'b1000000-0000-0000-0000-000000000001';\n\n-- 5.5 Bước 3: Chuyển sang 'validated'\nUPDATE public.reports SET status = 'validated' WHERE id = 'b1000000-0000-0000-0000-000000000001';\n\n-- 5.6 Tính toán động chính xác 100% bằng SQL trực tiếp từ 15 dòng dữ liệu thực tế:\n-- ONLINE_RATE: 657 / (657 + 137) * 100 = 657 / 794 * 100 = 82.7456% -> 82.75%\n-- ON_TIME_COMPLETION_RATE: (471 + 304) / 776 * 100 = 775 / 776 * 100 = 99.8711% -> 99.87%\n-- OVERDUE_COMPLETION_RATE: 1 / 776 * 100 = 0.1289% -> 0.13%\nINSERT INTO public.report_indicators (\n  report_id, indicator_definition_id, scope_type, scope_id,\n  calculated_value, formatted_value, target_status, calculation_details\n)\nSELECT \n  r.id AS report_id,\n  d.id AS indicator_definition_id,\n  'global' AS scope_type,\n  NULL AS scope_id,\n  CASE d.code\n    WHEN 'ONLINE_RATE' THEN \n      ROUND((SUM(st.received_online)::numeric / NULLIF(SUM(st.received_online + st.received_offline), 0) * 100)::numeric, 4)\n    WHEN 'ON_TIME_COMPLETION_RATE' THEN \n      ROUND((SUM(st.completed_early + st.completed_on_time)::numeric / NULLIF(SUM(st.completed_total), 0) * 100)::numeric, 4)\n    WHEN 'OVERDUE_COMPLETION_RATE' THEN \n      ROUND((SUM(st.completed_late)::numeric / NULLIF(SUM(st.completed_total), 0) * 100)::numeric, 4)\n  END AS calculated_value,\n  CASE d.code\n    WHEN 'ONLINE_RATE' THEN \n      TO_CHAR(ROUND((SUM(st.received_online)::numeric / NULLIF(SUM(st.received_online + st.received_offline), 0) * 100)::numeric, 2), 'FM990.00') || '%'\n    WHEN 'ON_TIME_COMPLETION_RATE' THEN \n      TO_CHAR(ROUND((SUM(st.completed_early + st.completed_on_time)::numeric / NULLIF(SUM(st.completed_total), 0) * 100)::numeric, 2), 'FM990.00') || '%'\n    WHEN 'OVERDUE_COMPLETION_RATE' THEN \n      TO_CHAR(ROUND((SUM(st.completed_late)::numeric / NULLIF(SUM(st.completed_total), 0) * 100)::numeric, 2), 'FM990.00') || '%'\n  END AS formatted_value,\n  CASE d.code\n    WHEN 'ONLINE_RATE' THEN \n      CASE WHEN (SUM(st.received_online)::numeric / NULLIF(SUM(st.received_online + st.received_offline), 0) * 100) >= d.target_value THEN 'achieved' ELSE 'critical' END\n    WHEN 'ON_TIME_COMPLETION_RATE' THEN \n      CASE WHEN (SUM(st.completed_early + st.completed_on_time)::numeric / NULLIF(SUM(st.completed_total), 0) * 100) >= d.target_value THEN 'achieved' ELSE 'critical' END\n    WHEN 'OVERDUE_COMPLETION_RATE' THEN \n      CASE WHEN (SUM(st.completed_late)::numeric / NULLIF(SUM(st.completed_total), 0) * 100) <= d.target_value THEN 'achieved' ELSE 'critical' END\n  END AS target_status,\n  CASE d.code\n    WHEN 'ONLINE_RATE' THEN \n      jsonb_build_object(\n        'received_online', SUM(st.received_online),\n        'received_offline', SUM(st.received_offline),\n        'new_received_total', SUM(st.received_online + st.received_offline),\n        'target_value', d.target_value,\n        'formula', format('%s / %s * 100', SUM(st.received_online), SUM(st.received_online + st.received_offline))\n      )\n    WHEN 'ON_TIME_COMPLETION_RATE' THEN \n      jsonb_build_object(\n        'completed_early', SUM(st.completed_early),\n        'completed_on_time', SUM(st.completed_on_time),\n        'completed_total', SUM(st.completed_total),\n        'target_value', d.target_value,\n        'formula', format('%s / %s * 100', SUM(st.completed_early + st.completed_on_time), SUM(st.completed_total))\n      )\n    WHEN 'OVERDUE_COMPLETION_RATE' THEN \n      jsonb_build_object(\n        'completed_late', SUM(st.completed_late),\n        'completed_total', SUM(st.completed_total),\n        'target_value', d.target_value,\n        'formula', format('%s / %s * 100', SUM(st.completed_late), SUM(st.completed_total))\n      )\n  END AS calculation_details\nFROM public.reports r\nCROSS JOIN public.indicator_definitions d\nJOIN public.report_field_statistics st ON st.report_id = r.id\nWHERE r.id = 'b1000000-0000-0000-0000-000000000001'\nGROUP BY r.id, d.id, d.code, d.target_value;\n\n-- 5.7 Thêm bài phân tích khách quan căn cứ dữ liệu thực tế (scope overview)\nINSERT INTO public.report_analysis (\n  report_id, scope_type, scope_id, title, generated_text, generated_by, source_metrics\n)\nSELECT\n  r.id AS report_id,\n  'overview' AS scope_type,\n  NULL AS scope_id,\n  'Báo cáo phân tích kết quả tiếp nhận và giải quyết TTHC Tháng 01/2026' AS title,\n  format(\n    'Trong kỳ Tháng 01/2026, toàn cơ quan tiếp nhận tổng cộng %s hồ sơ (%s hồ sơ trực tuyến, %s hồ sơ trực tiếp, %s hồ sơ từ kỳ trước chuyển qua). Tỷ lệ nộp hồ sơ trực tuyến đối với hồ sơ mới phát sinh đạt %s%% (%s/%s), hoàn thành chỉ tiêu quy định (80.00%%). Tổng số hồ sơ đã giải quyết trong kỳ là %s hồ sơ, trong đó giải quyết trước hạn %s hồ sơ, đúng hạn %s hồ sơ và quá hạn %s hồ sơ (thuộc lĩnh vực Đất đai). Tỷ lệ giải quyết đúng và trước hạn đạt %s%%, tỷ lệ quá hạn là %s%%. Số lượng hồ sơ đang trong quá trình giải quyết là %s hồ sơ, toàn bộ đều đang trong hạn quy định.',\n    SUM(st.received_total),\n    SUM(st.received_online),\n    SUM(st.received_offline),\n    SUM(st.carried_forward),\n    TO_CHAR(ROUND((SUM(st.received_online)::numeric / NULLIF(SUM(st.received_online + st.received_offline), 0) * 100)::numeric, 2), 'FM990.00'),\n    SUM(st.received_online),\n    SUM(st.received_online + st.received_offline),\n    SUM(st.completed_total),\n    SUM(st.completed_early),\n    SUM(st.completed_on_time),\n    SUM(st.completed_late),\n    TO_CHAR(ROUND((SUM(st.completed_early + st.completed_on_time)::numeric / NULLIF(SUM(st.completed_total), 0) * 100)::numeric, 2), 'FM990.00'),\n    TO_CHAR(ROUND((SUM(st.completed_late)::numeric / NULLIF(SUM(st.completed_total), 0) * 100)::numeric, 2), 'FM990.00'),\n    SUM(st.pending_total)\n  ) AS generated_text,\n  'Hệ thống Phân tích Thống kê TTHC' AS generated_by,\n  jsonb_build_object(\n    'received_total', SUM(st.received_total),\n    'received_online', SUM(st.received_online),\n    'received_offline', SUM(st.received_offline),\n    'carried_forward', SUM(st.carried_forward),\n    'completed_total', SUM(st.completed_total),\n    'completed_early', SUM(st.completed_early),\n    'completed_on_time', SUM(st.completed_on_time),\n    'completed_late', SUM(st.completed_late),\n    'pending_total', SUM(st.pending_total),\n    'online_rate', ROUND((SUM(st.received_online)::numeric / NULLIF(SUM(st.received_online + st.received_offline), 0) * 100)::numeric, 2),\n    'on_time_rate', ROUND((SUM(st.completed_early + st.completed_on_time)::numeric / NULLIF(SUM(st.completed_total), 0) * 100)::numeric, 2),\n    'overdue_rate', ROUND((SUM(st.completed_late)::numeric / NULLIF(SUM(st.completed_total), 0) * 100)::numeric, 2)\n  ) AS source_metrics\nFROM public.reports r\nJOIN public.report_field_statistics st ON st.report_id = r.id\nWHERE r.id = 'b1000000-0000-0000-0000-000000000001'\nGROUP BY r.id;\n\n-- 5.8 Bước 4: Chuyển sang 'submitted'\nUPDATE public.reports SET status = 'submitted' WHERE id = 'b1000000-0000-0000-0000-000000000001';\n\n-- 5.9 Bước 5: Chuyển sang 'approved'\nUPDATE public.reports \nSET status = 'approved',\n    approved_at = now(),\n    approved_by = 'Ban Lãnh đạo UBND'\nWHERE id = 'b1000000-0000-0000-0000-000000000001';\n\n-- 5.10 Bước 6: Chuyển sang 'locked' (Kích hoạt trigger tạo snapshot bất biến tự động)\nUPDATE public.reports \nSET status = 'locked',\n    locked_by = 'Chánh Văn phòng HĐND & UBND'\nWHERE id = 'b1000000-0000-0000-0000-000000000001';\n\n-- ==============================================================================\n-- 6. SEED KỲ BÁO CÁO 2 (DEMO-BC-2026-02): DỪNG Ở TRẠNG THÁI VALIDATED\n-- ==============================================================================\n\n-- 6.1 Bước 1: Tạo báo cáo với trạng thái 'draft'\nINSERT INTO public.reports (\n  id, report_code, report_name, report_type, \n  period_start, period_end, data_as_of, \n  status, created_by, notes\n) VALUES (\n  'b1000000-0000-0000-0000-000000000002',\n  'DEMO-BC-2026-02',\n  'Báo cáo TTHC Tháng 02/2026 (Đang thẩm định)',\n  'monthly',\n  '2026-02-01',\n  '2026-02-28',\n  '2026-02-28 23:59:59+07',\n  'draft',\n  'Cán bộ Tiếp nhận',\n  'Số liệu Tháng 02/2026 đang xử lý kiểm tra.'\n);\n\n-- 6.2 Khởi tạo nguồn dữ liệu cho kỳ báo cáo 2\nINSERT INTO public.report_sources (\n  id, report_id, source_type, source_name, original_filename, uploaded_by, import_status, notes\n) VALUES (\n  's1000000-0000-0000-0000-000000000002',\n  'b1000000-0000-0000-0000-000000000002',\n  'system',\n  'Trên Hệ thống các Bộ',\n  'he_thong_cac_bo_t2_2026.xlsx',\n  'Cán bộ Tiếp nhận',\n  'completed',\n  'Nguồn tổng hợp tháng 2'\n);\n\n-- 6.3 Khởi tạo số liệu cho kỳ báo cáo 2 (Hợp lệ 100%)\nINSERT INTO public.report_field_statistics (\n  report_id, source_id, field_id, field_name_snapshot, unit_id, unit_name_snapshot,\n  received_total, received_online, received_offline, carried_forward,\n  completed_total, completed_early, completed_on_time, completed_late,\n  pending_total, pending_on_time, pending_late, validation_status, notes\n) VALUES\n  ('b1000000-0000-0000-0000-000000000002', 's1000000-0000-0000-0000-000000000002', 'f1000000-0000-0000-0000-000000000001', 'Chứng thực', 'u1000000-0000-0000-0000-000000000001', 'Văn phòng HĐND & UBND', 280, 250, 30, 0, 275, 190, 85, 0, 5, 5, 0, 'valid', 'Số liệu tháng 2'),\n  ('b1000000-0000-0000-0000-000000000002', 's1000000-0000-0000-0000-000000000002', 'f1000000-0000-0000-0000-000000000002', 'Hộ tịch', 'u1000000-0000-0000-0000-000000000001', 'Văn phòng HĐND & UBND', 130, 110, 15, 5, 125, 75, 50, 0, 5, 5, 0, 'valid', 'Số liệu tháng 2');\n\n-- 6.4 Chuyển dần qua 'imported' và dừng ở 'validated'\nUPDATE public.reports SET status = 'imported' WHERE id = 'b1000000-0000-0000-0000-000000000002';\nUPDATE public.reports SET status = 'validated' WHERE id = 'b1000000-0000-0000-0000-000000000002';\n\n-- ==============================================================================\n-- 7. GHI NHẬT KÝ KIỂM TOÁN MẪU BẰNG FUNCTION write_audit_log (SECURITY DEFINER)\n-- ==============================================================================\nSELECT public.write_audit_log(\n  'SEED_INITIAL_DATA',\n  'system',\n  'system-seed-002',\n  jsonb_build_object(\n    'module', 'DEMO_SEED',\n    'reports_initialized', ARRAY['DEMO-BC-2026-01', 'DEMO-BC-2026-02'],\n    'status', 'success'\n  )\n);\n\n-- ==============================================================================\n-- 8. KHỐI KIỂM THỬ TỰ ĐỘNG VÀ BẢO ĐẢM TOÀN VẸN (AUTOMATED VERIFICATION ASSERTIONS)\n-- ==============================================================================\nDO $$\nDECLARE\n  v_units_count INTEGER;\n  v_fields_count INTEGER;\n  v_indicators_def_count INTEGER;\n  v_formula_errors_count INTEGER;\n  v_mapping_errors_count INTEGER;\n  v_locked_snapshots_count INTEGER;\n  v_global_duplicates_count INTEGER;\n  v_mismatched_source_count INTEGER;\n  v_audit_logs_count INTEGER;\n  v_sum_received_total INTEGER;\n  v_sum_received_online INTEGER;\n  v_sum_received_offline INTEGER;\n  v_sum_carried_forward INTEGER;\n  v_sum_completed_total INTEGER;\n  v_sum_completed_early INTEGER;\n  v_sum_completed_on_time INTEGER;\n  v_sum_completed_late INTEGER;\n  v_sum_pending_total INTEGER;\n  v_sum_pending_on_time INTEGER;\n  v_sum_pending_late INTEGER;\nBEGIN\n  -- 1. Kiểm tra bảng units\n  SELECT count(*) INTO v_units_count FROM public.units;\n  IF v_units_count < 3 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: Bảng units thiếu bản ghi (Hiện có: %, Yêu cầu: >= 3).', v_units_count;\n  END IF;\n\n  -- 2. Kiểm tra bảng fields\n  SELECT count(*) INTO v_fields_count FROM public.fields;\n  IF v_fields_count < 15 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: Bảng fields thiếu bản ghi (Hiện có: %, Yêu cầu: >= 15).', v_fields_count;\n  END IF;\n\n  -- 3. Kiểm tra bảng indicator_definitions\n  SELECT count(*) INTO v_indicators_def_count FROM public.indicator_definitions;\n  IF v_indicators_def_count < 3 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: Bảng indicator_definitions thiếu bản ghi (Hiện có: %, Yêu cầu: >= 3).', v_indicators_def_count;\n  END IF;\n\n  -- 4. Kiểm tra 4 công thức toán học\n  SELECT count(*) INTO v_formula_errors_count \n  FROM public.report_field_statistics \n  WHERE validation_status = 'error';\n\n  IF v_formula_errors_count > 0 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: Tồn tại % bản ghi số liệu vi phạm công thức toán học.', v_formula_errors_count;\n  END IF;\n\n  -- 5. Kiểm tra chính xác 100% các giá trị thống kê thực tế của kỳ BC-01\n  SELECT \n    SUM(received_total), SUM(received_online), SUM(received_offline), SUM(carried_forward),\n    SUM(completed_total), SUM(completed_early), SUM(completed_on_time), SUM(completed_late),\n    SUM(pending_total), SUM(pending_on_time), SUM(pending_late)\n  INTO\n    v_sum_received_total, v_sum_received_online, v_sum_received_offline, v_sum_carried_forward,\n    v_sum_completed_total, v_sum_completed_early, v_sum_completed_on_time, v_sum_completed_late,\n    v_sum_pending_total, v_sum_pending_on_time, v_sum_pending_late\n  FROM public.report_field_statistics\n  WHERE report_id = 'b1000000-0000-0000-0000-000000000001';\n\n  IF v_sum_received_total <> 808 OR v_sum_received_online <> 657 OR v_sum_received_offline <> 137 OR v_sum_carried_forward <> 14 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: Tổng nhóm Tiếp nhận không đúng (Nhận: 808/657/137/14, Thực tế: %/%/%/%).',\n      v_sum_received_total, v_sum_received_online, v_sum_received_offline, v_sum_carried_forward;\n  END IF;\n\n  IF v_sum_completed_total <> 776 OR v_sum_completed_early <> 471 OR v_sum_completed_on_time <> 304 OR v_sum_completed_late <> 1 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: Tổng nhóm Đã giải quyết không đúng (Nhận: 776/471/304/1, Thực tế: %/%/%/%).',\n      v_sum_completed_total, v_sum_completed_early, v_sum_completed_on_time, v_sum_completed_late;\n  END IF;\n\n  IF v_sum_pending_total <> 32 OR v_sum_pending_on_time <> 32 OR v_sum_pending_late <> 0 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: Tổng nhóm Đang giải quyết không đúng (Nhận: 32/32/0, Thực tế: %/%/%).',\n      v_sum_pending_total, v_sum_pending_on_time, v_sum_pending_late;\n  END IF;\n\n  -- 6. Kiểm tra ánh xạ lĩnh vực -> đơn vị\n  SELECT count(*) INTO v_mapping_errors_count\n  FROM public.report_field_statistics s\n  JOIN public.fields f ON f.id = s.field_id\n  WHERE s.unit_id <> f.unit_id;\n\n  IF v_mapping_errors_count > 0 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: Phát hiện % bản ghi sai lệch ánh xạ đơn vị so với bảng fields.', v_mapping_errors_count;\n  END IF;\n\n  -- 7. Kiểm tra nguồn dữ liệu thuộc đúng report_id\n  SELECT count(*) INTO v_mismatched_source_count\n  FROM public.report_field_statistics st\n  JOIN public.report_sources src ON src.id = st.source_id\n  WHERE st.report_id <> src.report_id;\n\n  IF v_mismatched_source_count > 0 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: Phát hiện % bản ghi có source_id không thuộc report_id.', v_mismatched_source_count;\n  END IF;\n\n  -- 8. Kiểm tra snapshot tự động cho báo cáo locked\n  SELECT count(*) INTO v_locked_snapshots_count\n  FROM public.report_snapshots s\n  JOIN public.reports r ON r.id = s.report_id\n  WHERE r.report_code = 'DEMO-BC-2026-01';\n\n  IF v_locked_snapshots_count < 1 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: Báo cáo DEMO-BC-2026-01 đã khóa nhưng chưa sinh snapshot tự động.';\n  END IF;\n\n  -- 9. Kiểm tra không có duplicate chỉ số scope global\n  SELECT count(*) INTO v_global_duplicates_count\n  FROM (\n    SELECT report_id, indicator_definition_id, count(*)\n    FROM public.report_indicators\n    WHERE scope_type = 'global'\n    GROUP BY report_id, indicator_definition_id\n    HAVING count(*) > 1\n  ) dups;\n\n  IF v_global_duplicates_count > 0 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: Trùng lặp chỉ số cấp global trong report_indicators.';\n  END IF;\n\n  -- 10. Kiểm tra audit log được ghi thành công qua function\n  SELECT count(*) INTO v_audit_logs_count FROM public.audit_logs;\n  IF v_audit_logs_count < 1 THEN\n    RAISE EXCEPTION 'Kiểm thử thất bại: write_audit_log chưa ghi nhận nhật ký kiểm toán vào bảng audit_logs.';\n  END IF;\n\n  RAISE NOTICE '==============================================================================';\n  RAISE NOTICE 'KIỂM THỬ TOÀN DIỆN THÀNH CÔNG 100%%! TẤT CẢ RÀNG BUỘC TOÁN HỌC & CSDL HỢP LỆ.';\n  RAISE NOTICE '==============================================================================';\nEND $$;\n\n-- ==============================================================================\n-- 9. TRUY VẤN KẾT QUẢ TỔNG HỢP SAU KHI SEED\n-- ==============================================================================\nSELECT \n  r.report_code,\n  r.report_name,\n  r.status,\n  COUNT(DISTINCT s.id) AS sources_count,\n  COUNT(DISTINCT st.id) AS statistics_count,\n  COUNT(DISTINCT i.id) AS indicators_count,\n  COUNT(DISTINCT a.id) AS analysis_count,\n  COUNT(DISTINCT sn.id) AS snapshot_count\nFROM public.reports r\nLEFT JOIN public.report_sources s ON s.report_id = r.id\nLEFT JOIN public.report_field_statistics st ON st.report_id = r.id\nLEFT JOIN public.report_indicators i ON i.report_id = r.id\nLEFT JOIN public.report_analysis a ON a.report_id = r.id\nLEFT JOIN public.report_snapshots sn ON sn.report_id = r.id\nWHERE r.report_code LIKE 'DEMO-%'\nGROUP BY r.id, r.report_code, r.report_name, r.status\nORDER BY r.report_code;\n";
